insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('2e34a8f4-f963-4f37-8c32-3c1c606d1c65', 1, array['הרשב״י']::text[], 'רבי שמעון בר יוחאי, מגדולי התנאים, תלמידו של רבי עקיבא. לפי המסורת חיבר את ספר הזוהר. יום ההילולה שלו, ל״ג בעומר, נחגג במירון בהשתתפות רבבות.', 'התנא האלוקי, מחבר ספר הזוהר. ההילולה בל״ג בעומר.', 18, 2, null, true, 'רבי שמעון בר יוחאי', 'rashbi');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('f6160848-2448-4d79-8728-7ab555b90fd5', 2, array['הרמב״ם']::text[], 'הרמב״ם, מחבר משנה תורה, מורה נבוכים ופירוש המשניות. נפטר במצרים והובא לקבורה בטבריה.', 'מגדולי הפוסקים והפילוסופים, מחבר משנה תורה.', 20, 10, null, true, 'רבנו משה בן מימון', 'rambam');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('10f541f3-f619-43ab-9ed5-07073ef74e7f', 3, null, 'רבי מאיר, מגדולי התנאים, תלמידו של רבי עקיבא. ציונו בטבריה, וההילולה נערכת בפסח שני.', 'התנא רבי מאיר. ההילולה בפסח שני.', 14, 2, null, true, 'רבי מאיר בעל הנס', 'rabbi-meir-baal-hanes');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('1fe10bda-5164-46af-b955-032490eca7a5', 4, array['האר״י הקדוש']::text[], 'רבי יצחק לוריא אשכנזי, האר״י הקדוש, מגדולי המקובלים. פעל בצפת ונפטר בה בצעירותו.', 'האר״י הקדוש, אבי תורת הקבלה של צפת.', 5, 5, null, true, 'רבי יצחק לוריא', 'haari');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('1fe10bda-5164-46af-b955-032490eca7a5', 5, array['מרן','הבית יוסף']::text[], 'רבי יוסף קארו, מחבר הבית יוסף והשולחן ערוך. ישב בצפת ונקבר בבית העלמין העתיק.', 'מרן הבית יוסף, מחבר השולחן ערוך.', 13, 1, null, true, 'רבי יוסף קארו', 'maran');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('8bb22945-7e7f-44d7-9fb4-15ca70b113be', 6, array['הבבא סאלי']::text[], 'רבי ישראל אבוחצירא, הבבא סאלי, עלה ממרוקו והתיישב בנתיבות. ההילולה בד׳ בשבט.', 'הבבא סאלי, מגדולי צדיקי מרוקו, ציונו בנתיבות.', 4, 11, null, true, 'רבי ישראל אבוחצירא', 'baba-sali');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('3f80c1d9-8751-476c-a348-44370cffd7d4', 7, null, 'רחל אמנו, אשת יעקב אבינו, נקברה בדרך אפרתה היא בית לחם.', 'רחל אמנו, אם ישראל. יום פטירתה בי״א בחשוון.', 11, 8, null, true, 'רחל אמנו', 'rachel-imenu');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('f33cafc7-9b32-46ce-9ead-414d6f8013cf', 8, null, 'רבי יונתן בן עוזיאל, גדול תלמידי הלל הזקן ומחבר תרגום יונתן לנביאים. ציונו בעמוקה.', 'התנא רבי יונתן בן עוזיאל, ציונו בעמוקה.', 26, 3, null, true, 'רבי יונתן בן עוזיאל', 'yonatan-ben-uziel');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('cfa188ad-21cf-466a-85b8-9dcd51675421', 9, array['האור החיים הקדוש']::text[], 'רבי חיים בן עטר, מחבר פירוש אור החיים על התורה. עלה ממרוקו לירושלים ונקבר בהר הזיתים.', 'האור החיים הקדוש, ציונו בהר הזיתים.', 15, 4, null, true, 'רבי חיים בן עטר', 'or-hachaim');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('3b24648b-e5bf-48c3-9f61-835ad7588fbd', 10, null, 'דוד המלך, מלך ישראל ומחבר ספר תהלים. לפי המסורת נפטר בחג השבועות.', 'נעים זמירות ישראל. יום ההילולה בחג השבועות.', 6, 3, null, true, 'דוד המלך', 'david-hamelech');
insert into tzadikim (site_id, ivr_code, aka, bio, bio_short, hebrew_death_day, hebrew_death_month, death_year_hebrew, is_published, name, slug) values ('aec34f95-d8e8-4b7a-89c8-b8408f221456', 11, null, 'רבי נחמן מברסלב, נינו של הבעל שם טוב, מחבר ליקוטי מוהר״ן. נקבר באומן.', 'רבי נחמן מברסלב, ציונו באומן.', 18, 7, null, true, 'רבי נחמן מברסלב', 'rabbi-nachman');
